/**
 * End-to-end regression tests: run the full pipeline on every fixture and check
 * the things that matter. When tuning weights or adding vocabulary, these tests
 * catch "fixed one file, broke three others".
 *
 * Fixtures are generated by `npm run fixtures` (scripts/generate-fixtures.ts).
 */
import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { readWorkbook, analyzeWorkbook, includedAssets, IngestError } from "@/lib/parser";
import type { Asset, Overrides, ParseResult } from "@/lib/types";
import { formatStorage } from "@/lib/extract/storage";

const TODAY = new Date("2026-11-13T00:00:00Z");

function load(name: string) {
  const buf = readFileSync(join(__dirname, "fixtures", name));
  return readWorkbook(name, buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength) as ArrayBuffer);
}
function parse(name: string, overrides?: Overrides): ParseResult {
  return analyzeWorkbook(load(name), overrides, TODAY);
}
const computers = (r: ParseResult) => includedAssets(r).filter((a) => a.kind === "computer");
function row(r: ParseResult, sheet: string, rowNumber: number): Asset {
  const a = includedAssets(r).find((x) => x.sheetName === sheet && x.rowNumber === rowNumber) ?? r.sheets.flatMap((s) => s.tables.flatMap((t) => t.assets)).find((x) => x.sheetName === sheet && x.rowNumber === rowNumber);
  if (!a) throw new Error(`no row ${sheet}!${rowNumber}`);
  return a;
}
function simple(a: Asset) {
  const f = a.fields;
  return {
    type: f.assetType?.value,
    manufacturer: f.manufacturer?.value,
    model: f.model?.value,
    serial: f.serialNumber?.value,
    cpu: f.cpu?.value,
    ram: f.ramGB?.value,
    storage: f.storage ? formatStorage(f.storage.value) : undefined,
    screen: f.screenInches?.value,
  };
}
const mappingOf = (r: ParseResult, sheet = 0, table = 0) =>
  Object.fromEntries(r.sheets[sheet]!.tables[table]!.mapping.map((m) => [m.header, m.target]));

describe("01 clean baseline", () => {
  const r = parse("01_clean.csv");
  it("maps every column and extracts every row", () => {
    expect(computers(r)).toHaveLength(5);
    expect(simple(row(r, "01_clean", 5))).toEqual({
      type: "server", manufacturer: "Dell", model: "PowerEdge R740", serial: "7XK9P23",
      cpu: "Intel Xeon Gold 6230", ram: 256, storage: "4 × 1.2 TB HDD", screen: undefined,
    });
  });
});

describe("02 the brief's spreadsheet", () => {
  const r = parse("02_assets_FINAL_v3_USE_THIS_ONE.xlsx");
  const sheet = r.sheets[0]!;
  it("finds the header on row 4 under the title lines", () => {
    expect(sheet.tables[0]!.table.headerRow).toBe(4);
  });
  it("maps the oddly named columns", () => {
    expect(mappingOf(r)).toMatchObject({ "Asset #": "assetTag", Device: "assetType", Make: "manufacturer", "S/N": "serialNumber", Processor: "cpu", Mem: "ramGB", HDD: "storage", "Assigned To": "assignedUser" });
  });
  it("splits the stuffed model cell", () => {
    expect(simple(row(r, "Sheet1", 5))).toMatchObject({ manufacturer: "Dell", model: "Latitude 5420", cpu: "Intel Core i7", ram: 16 });
    expect(row(r, "Sheet1", 5).fields.cpu?.method).toBe("parsed");
  });
  it("normalises messy values", () => {
    expect(simple(row(r, "Sheet1", 6)).ram).toBe(16); // "16 gig"
    expect(simple(row(r, "Sheet1", 7)).ram).toBe(8); // "8192 MB"
    expect(simple(row(r, "Sheet1", 9)).manufacturer).toBe("HP"); // "hewlett-packard"
  });
  it("keeps the monitor apart and skips the total line", () => {
    expect(row(r, "Sheet1", 10).kind).toBe("non-computer");
    expect(row(r, "Sheet1", 14).kind).toBe("skipped");
  });
  it("flags the copy sheet, the placeholder serial and the duplicate serial", () => {
    expect(r.sheets[1]).toMatchObject({ name: "Sheet1 (2)", status: "duplicate", included: false });
    expect(r.sheets[2]!.status).toBe("no-asset-data");
    expect(row(r, "Sheet1", 9).warnings.map((w) => w.code)).toContain("placeholder-serial");
    expect(r.duplicates).toEqual([{ serial: "5CG1234XYZ", assetIds: ["Sheet1!5", "Sheet1!12"] }]);
    expect(r.summary.computers).toBe(7);
  });
  it("lets the user include the copy sheet", () => {
    const r2 = parse("02_assets_FINAL_v3_USE_THIS_ONE.xlsx", { sheetInclusion: { "Sheet1 (2)": true } });
    expect(r2.summary.computers).toBe(13);
  });
});

describe("03 French CSV, semicolons, Windows-1252", () => {
  const r = parse("03_french_semicolon.csv");
  it("decodes and maps French headers", () => {
    expect(r.notes.join(" ")).toMatch(/Windows-1252/);
    expect(mappingOf(r)).toMatchObject({ "Numéro de série": "serialNumber", "Mémoire vive": "ramGB", "Écran": "screenInches", "Date d'achat": "purchaseDate" });
    expect(simple(row(r, "03_french_semicolon", 4))).toMatchObject({ ram: 32, storage: "1 TB NVMe", screen: 14 });
    expect(row(r, "03_french_semicolon", 2).fields.purchaseDate?.value).toBe("2022-03-15");
    expect(row(r, "03_french_semicolon", 6).kind).toBe("non-computer");
  });
});

describe("04 description-only column", () => {
  const r = parse("04_combined_description.xlsx");
  it("pulls every field out of free text", () => {
    expect(mappingOf(r)).toMatchObject({ Item: null, Description: "combined", Serial: "serialNumber" });
    expect(simple(row(r, "Inventory", 2))).toEqual({
      type: "laptop", manufacturer: "HP", model: "EliteBook 840 G8", serial: "5CD2345ABC",
      cpu: "Intel Core i5", ram: 16, storage: "256 GB SSD", screen: 14,
    });
    expect(row(r, "Inventory", 7).kind).toBe("non-computer"); // keyboard
  });
});

describe("05 multi-sheet", () => {
  const r = parse("05_multi_sheet.xlsx");
  it("uses header units and ignores the lookup / empty sheets", () => {
    expect(simple(row(r, "Laptops", 3))).toMatchObject({ ram: 32, storage: "1 TB", screen: 14 });
    expect(r.sheets.find((s) => s.name === "Old lookup")).toMatchObject({ hidden: true, included: false });
    expect(r.sheets.find((s) => s.name === "Empty")!.status).toBe("empty");
    expect(row(r, "Servers", 2).warnings.map((w) => w.code)).toContain("warranty-expired");
    expect(r.summary.byType).toEqual({ laptop: 3, server: 3 });
  });
});

describe("06 no header", () => {
  const r = parse("06_no_header.csv");
  it("identifies columns from content alone and keeps row 1 as data", () => {
    expect(r.sheets[0]!.tables[0]!.table.headerRow).toBeNull();
    expect(computers(r)).toHaveLength(5);
    expect(simple(row(r, "06_no_header", 1))).toMatchObject({ manufacturer: "Dell", serial: "5CG1234XYZ", ram: 16, storage: "512 GB SSD" });
  });
});

describe("07 mixed units", () => {
  const r = parse("07_mixed_units.xlsx");
  it("normalises every spelling", () => {
    const rams = [2, 3, 4, 5, 7].map((n) => simple(row(r, "Fleet", n)).ram);
    expect(rams).toEqual([16, 16, 16, 8, 8]);
    expect(simple(row(r, "Fleet", 3)).screen).toBe(14); // 35.6 cm
    expect(simple(row(r, "Fleet", 7)).screen).toBe(15.6); // 15,6"
    expect(row(r, "Fleet", 6).warnings.map((w) => w.code)).toContain("suspicious-ram"); // 2400 = MHz
  });
});

describe("08 peripherals and totals", () => {
  const r = parse("08_peripherals_and_totals.xlsx");
  it("separates computers from accessories and ignores Qty/Price", () => {
    expect(mappingOf(r)).toMatchObject({ Qty: null, Price: null });
    expect(r.summary.computers).toBe(2);
    expect(r.summary.nonComputers).toBe(4);
    expect(r.summary.skippedRows).toBe(1);
  });
});

describe("09 merged two-row header", () => {
  const r = parse("09_merged_two_row_header.xlsx");
  it("combines group and column titles", () => {
    expect(r.sheets[0]!.tables[0]!.table.headerRow).toBe(2);
    expect(computers(r)).toHaveLength(3);
    expect(simple(row(r, "Inventory", 5)).type).toBe("workstation");
  });
});

describe("10 two tables in one sheet", () => {
  const r = parse("10_two_tables_one_sheet.xlsx");
  it("detects both tables with their own headers", () => {
    const tables = r.sheets[0]!.tables;
    expect(tables.map((t) => t.table.headerRow)).toEqual([2, 8]);
    expect(tables[1]!.table.title).toBe("SERVERS");
    expect(simple(row(r, "IT", 9))).toMatchObject({ type: "server", manufacturer: "Dell", ram: 128 });
  });
});

describe("11 weird column names", () => {
  const r = parse("11_weird_column_names.xlsx");
  it("maps abbreviations and typos", () => {
    expect(mappingOf(r)).toMatchObject({ Proc: "cpu", "Disk Size": "storage", "S/N": "serialNumber", Mfr: "manufacturer", Memmory: "ramGB", "Form Factor": "assetType", Display: "screenInches" });
  });
});

describe("12 duplicates", () => {
  const r = parse("12_duplicates.csv");
  it("matches serials regardless of case and dashes", () => {
    expect(r.duplicates).toHaveLength(1);
    expect(row(r, "12_duplicates", 4).warnings.map((w) => w.code)).toContain("placeholder-serial");
    expect(row(r, "12_duplicates", 6).warnings.map((w) => w.code)).toContain("missing-serial");
  });
});

describe("16 unfamiliar (German) headers", () => {
  const r = parse("16_german_headers.xlsx");
  it("falls back to content-based detection", () => {
    expect(r.sheets[0]!.tables[0]!.table.headerRow).toBe(1);
    expect(computers(r)).toHaveLength(4);
    expect(simple(row(r, "Inventar", 2))).toMatchObject({ type: "laptop", manufacturer: "Dell", serial: "5CG1234XYZ", ram: 16, storage: "512 GB SSD", screen: 14 });
  });
});

describe("user corrections", () => {
  it("re-applies a manual column mapping", () => {
    const r = parse("01_clean.csv", { tables: { "0.0.0": { columns: { 3: null } } } });
    expect(row(r, "01_clean", 2).fields.serialNumber).toBeUndefined();
  });
  it("applies a forced header row", () => {
    const r = parse("06_no_header.csv", { tables: { "0.0.0": { headerRow: "none" } } });
    expect(r.sheets[0]!.tables[0]!.table.headerRow).toBeNull();
  });
  it("applies manual cell edits through the normaliser", () => {
    const r = parse("01_clean.csv", { cellEdits: { "01_clean!2": { ramGB: "32 gig" } } });
    expect(row(r, "01_clean", 2).fields.ramGB).toMatchObject({ value: 32, method: "manual", confidence: 1 });
  });
});

describe("errors", () => {
  it.each([
    ["13_empty.xlsx", null],
    ["14_corrupt.xlsx", "corrupt"],
    ["15_not_a_spreadsheet.pdf", "unsupported"],
  ])("%s", (name, code) => {
    if (code === null) {
      expect(parse(name).sheets[0]!.status).toBe("empty");
      return;
    }
    try {
      load(name);
      throw new Error("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(IngestError);
      expect((e as IngestError).code).toBe(code);
    }
  });
});
